head.script:
scwin.onpageload = function () {
    // 결함 재현은 아래 [gridLayout 동적 생성] 버튼 클릭 시 수행.
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};

// [재현] w2:gridLayout 을 $p.dynamicCreate 로 동적 생성 → CSS insertRule 파싱 예외 발생 확인
scwin.btn_reproduce_onclick = async function () {
    scwin.btn_clear_onclick();

    let strNameSpace = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    // 기존 target 있으면 제거 (반복 재현)
    if (typeof target1 !== 'undefined' && target1) {
        try { target1.remove(); } catch (ignore) {}
    }

    // 2열 x 3행 gridLayout (자식 없이 빈 상태)
    let strTarget = '';
    strTarget += '<w2:gridLayout ' + strNameSpace + ' style="width:400px; height:200px;" gridTemplateColumns="1fr 1fr;" gridTemplateRows="1fr 1fr 1fr;" gridColumnGap="1px;" gridRowGap="1px;" gridColumn="1:1:1:2:2:2;" gridRow="1:2:3:1:2:3;" rowShow="1:1:1:1:1:1;">';
    strTarget += '</w2:gridLayout>';

    try {
        scwin.target1 = await $p.dynamicCreate("target1", "gridLayout", strTarget, target_area);
        let el = document.getElementById(scwin.target1 ? scwin.target1.id : "");
        scwin.setReturnValue("동적 생성 호출 완료 (예외 없음)");
        scwin.setReturnValue("gridLayout 엘리먼트 렌더 여부 : " + (el ? "렌더됨" : "미렌더(null)"));
    } catch (e) {
        scwin.setReturnValue("[실제-결함] gridLayout 동적 생성 중 예외 발생");
        scwin.setReturnValue(e.name + " : " + e.message);
    }
};
